"""Command-line interface for the ComfyUI Agent."""

import atexit
import json
import logging
import signal
import threading

import typer
from rich.console import Console
from rich.panel import Panel

from .config import AGENT_MODEL, COMFYUI_URL, COMFYUI_DATABASE, ANTHROPIC_API_KEY, LOG_DIR
from .logging_config import setup_logging
from .tools import comfy_inspect, comfy_discover, session_tools

app = typer.Typer(
    help="ComfyUI Agent — AI co-pilot for ComfyUI workflows",
    no_args_is_help=True,
)
console = Console()


@app.command()
def run(
    session: str = typer.Option(
        None, "--session", "-s",
        help="Named session for memory persistence",
    ),
    verbose: bool = typer.Option(
        False, "--verbose", "-v",
        help="Show debug logging (API timing, tool execution, context management)",
    ),
):
    """Start an interactive agent session."""
    # Configure logging
    setup_logging(
        level=logging.DEBUG if verbose else logging.WARNING,
        log_file=LOG_DIR / "agent.log",
    )
    # Validate API key
    if not ANTHROPIC_API_KEY:
        console.print(
            "[red]ANTHROPIC_API_KEY not set.[/red]\n"
            "Setup steps:\n"
            "  1. Copy .env.example to .env\n"
            "  2. Get a key from https://console.anthropic.com/\n"
            "  3. Add: ANTHROPIC_API_KEY=sk-ant-...\n"
        )
        raise typer.Exit(1)

    # Show header
    console.print(Panel.fit(
        f"[bold blue]ComfyUI Agent[/bold blue]\n"
        f"Model: {AGENT_MODEL}\n"
        f"ComfyUI: {COMFYUI_URL}\n"
        f"Database: {COMFYUI_DATABASE}",
        title="ComfyUI Agent v0.2",
    ))

    # Load session context for system prompt injection
    session_context = None
    if session:
        console.print(f"[dim]Session: {session}[/dim]")
        # Restore session state
        load_result = json.loads(session_tools.handle("load_session", {"name": session}))
        if "error" not in load_result:
            console.print(f"[dim]Restored session from {load_result.get('saved_at', '?')}[/dim]")
            if load_result.get("workflow_restored"):
                console.print(f"[dim]Workflow loaded: {load_result.get('workflow_path')}[/dim]")
            if load_result.get("notes_count", 0) > 0:
                console.print(f"[dim]{load_result['notes_count']} note(s) from previous session[/dim]")
            # Build session context for system prompt
            session_context = {
                "name": session,
                "notes": load_result.get("notes", []),
                "workflow": {
                    "loaded_path": load_result.get("workflow_path"),
                    "format": load_result.get("workflow_format"),
                    "history_depth": 0,
                },
            }

    console.print("[dim]Type your question or command. 'quit' to exit.[/dim]\n")

    # Import here to avoid loading anthropic at CLI startup
    from .main import create_client, run_interactive, request_shutdown

    client = create_client()

    # Graceful shutdown: save session on SIGTERM or atexit
    _shutdown_done = threading.Event()

    def _save_and_exit(signum=None, frame=None):
        if _shutdown_done.is_set():
            return
        _shutdown_done.set()
        request_shutdown()
        if session:
            try:
                save_result = json.loads(
                    session_tools.handle("save_session", {"name": session})
                )
                if "saved" in save_result:
                    console.print(f"\n[dim]Session '{session}' saved.[/dim]")
            except Exception:
                pass

    signal.signal(signal.SIGTERM, _save_and_exit)
    atexit.register(
        lambda: _save_and_exit() if session and not _shutdown_done.is_set() else None
    )

    # Streaming callbacks
    _streamed_any = False

    def on_text_delta(text: str):
        nonlocal _streamed_any
        _streamed_any = True
        print(text, end="", flush=True)

    def on_tool_call(name: str, inp: dict):
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Newline after streamed text
            _streamed_any = False
        inp_summary = json.dumps(inp, default=str, sort_keys=True)
        if len(inp_summary) > 80:
            inp_summary = inp_summary[:77] + "..."
        console.print(f"  [dim]-> {name}({inp_summary})[/dim]")

    def on_stream_end():
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Final newline after streamed text
            _streamed_any = False

    def on_user_input() -> str | None:
        try:
            return console.input("[bold cyan]> [/bold cyan]")
        except (KeyboardInterrupt, EOFError):
            console.print()
            return None

    run_interactive(
        client,
        session_context=session_context,
        on_text_delta=on_text_delta,
        on_tool_call=on_tool_call,
        on_stream_end=on_stream_end,
        on_user_input=on_user_input,
    )

    # Save session on normal exit (atexit handles abnormal exit)
    _save_and_exit()

    console.print("\n[dim]Goodbye![/dim]")


@app.command()
def inspect():
    """Quick summary of the local ComfyUI installation."""
    console.print("[bold]ComfyUI Installation Summary[/bold]\n")

    # Models summary
    result = json.loads(comfy_inspect.handle("get_models_summary", {}))
    if "error" in result:
        console.print(f"[red]Models: {result['error']}[/red]")
    else:
        console.print(f"[bold]Models[/bold] ({result['directory']})")
        for model_type, count in sorted(result["types"].items()):
            console.print(f"  {model_type}: {count} file(s)")
        console.print()

    # Custom nodes
    result = json.loads(comfy_inspect.handle("list_custom_nodes", {}))
    if "error" in result:
        console.print(f"[red]Custom nodes: {result['error']}[/red]")
    else:
        console.print(f"[bold]Custom Node Packs[/bold] ({result['count']} installed)")
        for pack in result["packs"]:
            name = pack["name"]
            markers = []
            if pack.get("registers_nodes"):
                markers.append("nodes")
            if pack.get("has_readme"):
                markers.append("readme")
            suffix = f" [{', '.join(markers)}]" if markers else ""
            console.print(f"  {name}{suffix}")


@app.command()
def parse(
    workflow: str = typer.Argument(..., help="Path to workflow JSON file"),
):
    """Analyze a ComfyUI workflow file."""
    from pathlib import Path

    path = Path(workflow)
    if not path.exists():
        console.print(f"[red]File not found: {workflow}[/red]")
        raise typer.Exit(1)

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        console.print(f"[red]Invalid JSON: {e}[/red]")
        raise typer.Exit(1)

    # Detect format and extract nodes
    if "nodes" in data and isinstance(data["nodes"], list):
        fmt = "UI format"
        # Check for embedded API format in extra.prompt
        api_data = data.get("extra", {}).get("prompt")
        if api_data and isinstance(api_data, dict):
            # Has embedded API format
            nodes = {
                k: v for k, v in api_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
        else:
            # UI-only — convert nodes array to dict keyed by ID
            nodes = {}
            for node in data["nodes"]:
                nid = str(node.get("id", ""))
                node_type = node.get("type", "Unknown")
                widgets = node.get("widgets_values", [])
                nodes[nid] = {
                    "class_type": node_type,
                    "inputs": {},  # Can't fully reconstruct without object_info
                    "_widgets_values": widgets,
                }
    else:
        fmt = "API format"
        nodes = {
            k: v for k, v in data.items()
            if isinstance(v, dict) and "class_type" in v
        }

    console.print(f"[bold]Workflow:[/bold] {path.name}")
    console.print(f"[bold]Format:[/bold] {fmt}")
    console.print(f"[bold]Nodes:[/bold] {len(nodes)}")
    console.print()

    # List nodes by class type
    class_counts: dict[str, int] = {}
    for node in nodes.values():
        ct = node.get("class_type", "Unknown")
        class_counts[ct] = class_counts.get(ct, 0) + 1

    console.print("[bold]Node types:[/bold]")
    for ct, count in sorted(class_counts.items()):
        suffix = f" (×{count})" if count > 1 else ""
        console.print(f"  {ct}{suffix}")

    # Show editable fields (API format only — UI format lacks field names)
    api_nodes = {
        nid: n for nid, n in nodes.items()
        if n.get("inputs") and not n.get("_widgets_values")
    }
    if api_nodes:
        console.print("\n[bold]Editable fields:[/bold]")
        for nid, node in sorted(api_nodes.items()):
            ct = node.get("class_type", "?")
            for field, value in node.get("inputs", {}).items():
                if isinstance(value, list):
                    continue  # connection
                val_repr = repr(value)
                if len(val_repr) > 50:
                    val_repr = val_repr[:47] + "..."
                console.print(f"  [{nid}] {ct}.{field} = {val_repr}")
    elif fmt == "UI format":
        console.print(
            "\n[dim]UI-format workflow — editable fields require ComfyUI "
            "running (use interactive mode to analyze with /object_info).[/dim]"
        )


@app.command()
def sessions():
    """List saved agent sessions."""
    result = json.loads(session_tools.handle("list_sessions", {}))
    if result["count"] == 0:
        console.print("[dim]No saved sessions. Use --session NAME with 'run' to create one.[/dim]")
        return

    console.print(f"[bold]Saved Sessions[/bold] ({result['count']})\n")
    for s in result["sessions"]:
        name = s["name"]
        saved_at = s.get("saved_at", "?")
        notes = s.get("notes_count", 0)
        wf = " [workflow]" if s.get("has_workflow") else ""
        notes_str = f" [{notes} note(s)]" if notes else ""
        console.print(f"  [bold]{name}[/bold]  {saved_at}{wf}{notes_str}")


@app.command()
def search(
    query: str = typer.Argument(..., help="Search query for models or nodes"),
    nodes: bool = typer.Option(False, "--nodes", "-n", help="Search custom node packs"),
    models: bool = typer.Option(False, "--models", "-m", help="Search model registry"),
    node_type: bool = typer.Option(
        False, "--node-type", "-t",
        help="Search by specific node class_type",
    ),
    huggingface: bool = typer.Option(
        False, "--hf", help="Search HuggingFace instead of local registry",
    ),
    model_type: str = typer.Option(
        None, "--type",
        help="Filter models by type (checkpoint, lora, vae, controlnet)",
    ),
):
    """Search for custom nodes or models."""
    if node_type or nodes:
        by = "node_type" if node_type else "name"
        result = json.loads(comfy_discover.handle("search_custom_nodes", {
            "query": query, "by": by,
        }))
        if "error" in result:
            console.print(f"[red]{result['error']}[/red]")
            return

        if result.get("match") == "exact":
            pack = result["pack"]
            status = "[green]installed[/green]" if pack["installed"] else "[yellow]not installed[/yellow]"
            console.print(f"[bold]{result['node_type']}[/bold] -> {pack['title']} ({status})")
            console.print(f"  {pack['url']}")
            console.print(f"  {pack['node_count']} node types in this pack")
        elif result.get("results"):
            console.print(f"[bold]{result.get('total_matches', len(result['results']))} matches[/bold]\n")
            for r in result["results"]:
                title = r.get("pack_title") or r.get("title", "?")
                url = r.get("pack_url") or r.get("url", "")
                installed = r.get("installed", False)
                status = "[green]installed[/green]" if installed else ""
                desc = r.get("description", "")
                console.print(f"  [bold]{title}[/bold] {status}")
                if desc:
                    console.print(f"    {desc[:100]}")
                if url:
                    console.print(f"    [dim]{url}[/dim]")
        else:
            console.print(f"[yellow]No results for '{query}'[/yellow]")
    else:
        # Default: search models
        source = "huggingface" if huggingface else "registry"
        params = {"query": query, "source": source}
        if model_type:
            params["model_type"] = model_type

        result = json.loads(comfy_discover.handle("search_models", params))
        if "error" in result:
            console.print(f"[red]{result['error']}[/red]")
            return

        if result.get("results"):
            console.print(
                f"[bold]{result.get('total_matches', len(result['results']))} matches[/bold] "
                f"(source: {result['source']})\n"
            )
            for r in result["results"]:
                name = r.get("name", "?")
                mtype = r.get("type", "")
                base = r.get("base", "")
                size = r.get("size", "")
                installed = r.get("installed", False)
                status = " [green]installed[/green]" if installed else ""

                console.print(f"  [bold]{name}[/bold]{status}")
                parts = [p for p in [mtype, base, size] if p]
                if parts:
                    console.print(f"    {' | '.join(parts)}")
                url = r.get("url", "")
                if url:
                    console.print(f"    [dim]{url}[/dim]")
        else:
            console.print(f"[yellow]No results for '{query}'[/yellow]")


@app.command()
def mcp():
    """Start the MCP server (stdio transport).

    Exposes all agent tools via the Model Context Protocol.
    Configure in Claude Desktop or Claude Code settings.
    """
    from .mcp_server import main as mcp_main
    mcp_main()


if __name__ == "__main__":
    app()

"""Discovery tools — search for custom node packs and models.

Primary data source: ComfyUI Manager's local JSON registries
(custom-node-list.json, extension-node-map.json, model-list.json).
These ship with ComfyUI-Manager and cover 4,000+ packs and 31,000+ node types.

Secondary: HuggingFace Hub API for broader model search.

Includes freshness tracking to detect stale registry data and suggest updates.
"""

import json
import time
from pathlib import Path

import httpx

from ..config import COMFYUI_URL, CUSTOM_NODES_DIR, MODELS_DIR
from ..rate_limiter import HUGGINGFACE_LIMITER
from ._util import to_json

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "search_custom_nodes",
        "description": (
            "Search for custom node packs by name/description, or find which "
            "pack provides a specific node type. Uses ComfyUI Manager's "
            "registry (4,000+ packs, 31,000+ mapped node types). "
            "Shows whether each result is already installed locally."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": (
                        "Search term — either a pack name/keyword "
                        "(e.g. 'IPAdapter', 'upscaler', 'video') or a specific "
                        "node class_type (e.g. 'IPAdapterUnifiedLoader')."
                    ),
                },
                "by": {
                    "type": "string",
                    "enum": ["name", "node_type"],
                    "description": (
                        "Search mode: 'name' searches pack titles and descriptions, "
                        "'node_type' finds which pack provides a specific node class. "
                        "Default: 'name'."
                    ),
                },
                "max_results": {
                    "type": "integer",
                    "description": "Max results to return (default 10).",
                },
            },
            "required": ["query"],
        },
    },
    {
        "name": "search_models",
        "description": (
            "Search for models by name, type, or base model. Searches the "
            "ComfyUI Manager model registry (500+ curated entries with direct "
            "download URLs) or HuggingFace Hub for broader results. "
            "Cross-references with locally installed model files."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": (
                        "Search term — model name, type, or keyword "
                        "(e.g. 'FLUX', 'anime lora', 'controlnet depth')."
                    ),
                },
                "model_type": {
                    "type": "string",
                    "description": (
                        "Filter by model type: checkpoint, lora, vae, controlnet, "
                        "clip, upscale, embedding, etc. Matches against the "
                        "'type' field in the registry."
                    ),
                },
                "source": {
                    "type": "string",
                    "enum": ["registry", "huggingface"],
                    "description": (
                        "Where to search: 'registry' uses ComfyUI Manager's "
                        "curated list (fast, offline), 'huggingface' searches "
                        "HuggingFace Hub (broader, needs internet). Default: 'registry'."
                    ),
                },
                "max_results": {
                    "type": "integer",
                    "description": "Max results to return (default 10).",
                },
            },
            "required": ["query"],
        },
    },
    {
        "name": "find_missing_nodes",
        "description": (
            "Analyze a workflow to find which custom nodes are missing and "
            "suggest where to get them. Checks every node class_type against "
            "the live ComfyUI instance, then looks up missing ones in the "
            "ComfyUI Manager registry. Essential for importing shared workflows."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": (
                        "Path to workflow JSON file. If omitted, uses the "
                        "currently loaded workflow from workflow_patch."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "check_registry_freshness",
        "description": (
            "Check how fresh the local discovery data is. Reports the age of "
            "ComfyUI Manager registry files (custom-node-list, extension-node-map, "
            "model-list) and local model directories. Helps decide whether to use "
            "local cache or fetch updated data from CivitAI/HuggingFace. "
            "Use refresh=true to clear the in-memory cache and force a reload."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "refresh": {
                    "type": "boolean",
                    "description": (
                        "If true, clears the in-memory registry cache so the next "
                        "search reloads from disk. Default: false."
                    ),
                },
            },
            "required": [],
        },
    },
]

# ---------------------------------------------------------------------------
# Registry cache (loaded once per session from local ComfyUI Manager files)
# ---------------------------------------------------------------------------

_MANAGER_DIR = CUSTOM_NODES_DIR / "ComfyUI-Manager"

_cache: dict = {
    "custom_nodes": None,     # list[dict] from custom-node-list.json
    "extension_map": None,    # dict from extension-node-map.json
    "node_to_pack": None,     # dict[str, dict] — node_type -> pack info
    "model_list": None,       # list[dict] from model-list.json
}

# Freshness tracking — records when each cache was last loaded
_freshness: dict = {
    "custom_nodes_loaded_at": None,   # epoch timestamp
    "extension_map_loaded_at": None,
    "model_list_loaded_at": None,
}

# Staleness thresholds (seconds)
_STALE_THRESHOLD = 7 * 24 * 3600   # 7 days — registry files update infrequently
_WARN_THRESHOLD = 30 * 24 * 3600   # 30 days — strongly suggest update


def _load_custom_nodes() -> list[dict]:
    """Load and cache custom-node-list.json."""
    if _cache["custom_nodes"] is not None:
        return _cache["custom_nodes"]

    path = _MANAGER_DIR / "custom-node-list.json"
    if not path.exists():
        return []

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        _cache["custom_nodes"] = data.get("custom_nodes", [])
        _freshness["custom_nodes_loaded_at"] = time.time()
    except Exception:
        _cache["custom_nodes"] = []

    return _cache["custom_nodes"]


def _load_extension_map() -> dict:
    """Load and cache extension-node-map.json."""
    if _cache["extension_map"] is not None:
        return _cache["extension_map"]

    path = _MANAGER_DIR / "extension-node-map.json"
    if not path.exists():
        return {}

    try:
        _cache["extension_map"] = json.loads(path.read_text(encoding="utf-8"))
        _freshness["extension_map_loaded_at"] = time.time()
    except Exception:
        _cache["extension_map"] = {}

    return _cache["extension_map"]


def _build_node_to_pack() -> dict[str, dict]:
    """Build reverse index: node_type -> {url, title, node_types}."""
    if _cache["node_to_pack"] is not None:
        return _cache["node_to_pack"]

    ext_map = _load_extension_map()
    index = {}
    for url, entry in ext_map.items():
        if not isinstance(entry, list) or len(entry) < 2:
            continue
        node_types = entry[0] if isinstance(entry[0], list) else []
        meta = entry[1] if isinstance(entry[1], dict) else {}
        title = meta.get("title_aux", url.split("/")[-1] if "/" in url else url)

        pack_info = {"url": url, "title": title, "node_count": len(node_types)}
        for nt in node_types:
            index[nt] = pack_info

    _cache["node_to_pack"] = index
    return index


def _load_model_list() -> list[dict]:
    """Load and cache model-list.json."""
    if _cache["model_list"] is not None:
        return _cache["model_list"]

    path = _MANAGER_DIR / "model-list.json"
    if not path.exists():
        return []

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        _cache["model_list"] = data.get("models", [])
        _freshness["model_list_loaded_at"] = time.time()
    except Exception:
        _cache["model_list"] = []

    return _cache["model_list"]


def _is_pack_installed(reference_url: str) -> bool:
    """Check if a custom node pack is installed locally."""
    if not CUSTOM_NODES_DIR.exists():
        return False
    # Extract folder name from git URL
    folder = reference_url.rstrip("/").split("/")[-1]
    if folder.endswith(".git"):
        folder = folder[:-4]
    return (CUSTOM_NODES_DIR / folder).is_dir()


def _is_model_installed(filename: str, save_path: str) -> bool:
    """Check if a model file exists in the expected directory."""
    if not MODELS_DIR.exists():
        return False
    target = MODELS_DIR / save_path / filename
    return target.exists()


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_search_custom_nodes(tool_input: dict) -> str:
    query = tool_input["query"]
    by = tool_input.get("by", "name")
    max_results = tool_input.get("max_results", 10)

    if by == "node_type":
        return _search_by_node_type(query, max_results)
    else:
        return _search_by_name(query, max_results)


def _search_by_node_type(query: str, max_results: int) -> str:
    """Find which pack provides a specific node type."""
    index = _build_node_to_pack()

    if not index:
        return to_json({
            "error": (
                "ComfyUI Manager not found. Install it from "
                "https://github.com/ltdrdata/ComfyUI-Manager"
            ),
        })

    # Exact match first
    if query in index:
        pack = index[query]
        return to_json({
            "match": "exact",
            "node_type": query,
            "pack": {
                "title": pack["title"],
                "url": pack["url"],
                "node_count": pack["node_count"],
                "installed": _is_pack_installed(pack["url"]),
            },
        })

    # Fuzzy match — case-insensitive substring, sorted for determinism
    query_lower = query.lower()
    matches = []
    seen_packs = set()
    for nt, pack in sorted(index.items()):
        if query_lower in nt.lower() and pack["url"] not in seen_packs:
            seen_packs.add(pack["url"])
            matches.append({
                "node_type": nt,
                "pack_title": pack["title"],
                "pack_url": pack["url"],
                "installed": _is_pack_installed(pack["url"]),
            })
            if len(matches) >= max_results:
                break

    if not matches:
        return to_json({
            "match": "none",
            "node_type": query,
            "message": f"No pack found providing '{query}'. Check the spelling.",
            "total_known_types": len(index),
        })

    return to_json({
        "match": "fuzzy",
        "query": query,
        "results": matches,
        "total_matches": len(matches),
    })


def _search_by_name(query: str, max_results: int) -> str:
    """Search custom node packs by title/description/author."""
    packs = _load_custom_nodes()

    if not packs:
        return to_json({
            "error": (
                "ComfyUI Manager not found. Install it from "
                "https://github.com/ltdrdata/ComfyUI-Manager"
            ),
        })

    query_lower = query.lower()
    query_words = query_lower.split()
    scored = []

    for pack in packs:
        title = pack.get("title", "")
        desc = pack.get("description", "")
        author = pack.get("author", "")
        searchable = f"{title} {desc} {author}".lower()

        # Score: all words match > some words match
        word_hits = sum(1 for w in query_words if w in searchable)
        if word_hits == 0:
            continue

        # Boost exact title match
        score = word_hits
        if query_lower in title.lower():
            score += 10

        ref = pack.get("reference", "")
        scored.append((score, {
            "title": title,
            "author": author,
            "description": desc[:200] if desc else "",
            "url": ref,
            "install_type": pack.get("install_type", ""),
            "installed": _is_pack_installed(ref) if ref else False,
        }))

    scored.sort(key=lambda x: (-x[0], x[1].get("title", "")))
    results = [r for _, r in scored[:max_results]]

    return to_json({
        "query": query,
        "results": results,
        "total_matches": len(scored),
        "showing": len(results),
    })


def _handle_search_models(tool_input: dict) -> str:
    query = tool_input["query"]
    model_type = tool_input.get("model_type")
    source = tool_input.get("source", "registry")
    max_results = tool_input.get("max_results", 10)

    if source == "huggingface":
        return _search_huggingface(query, model_type, max_results)
    else:
        return _search_model_registry(query, model_type, max_results)


def _search_model_registry(query: str, model_type: str | None, max_results: int) -> str:
    """Search ComfyUI Manager's model-list.json."""
    models = _load_model_list()

    if not models:
        return to_json({
            "error": (
                "ComfyUI Manager model list not found. Install ComfyUI Manager "
                "or try source='huggingface' for online search."
            ),
        })

    query_lower = query.lower()
    query_words = query_lower.split()
    scored = []

    for model in models:
        name = model.get("name", "")
        mtype = model.get("type", "")
        base = model.get("base", "")
        desc = model.get("description", "")
        searchable = f"{name} {mtype} {base} {desc}".lower()

        # Apply type filter if given
        if model_type and model_type.lower() not in mtype.lower():
            continue

        word_hits = sum(1 for w in query_words if w in searchable)
        if word_hits == 0:
            continue

        score = word_hits
        if query_lower in name.lower():
            score += 10

        filename = model.get("filename", "")
        save_path = model.get("save_path", "")

        scored.append((score, {
            "name": name,
            "type": mtype,
            "base": base,
            "description": desc[:200] if desc else "",
            "filename": filename,
            "url": model.get("url", ""),
            "size": model.get("size", ""),
            "save_path": save_path,
            "installed": _is_model_installed(filename, save_path) if filename and save_path else False,
        }))

    scored.sort(key=lambda x: (-x[0], x[1].get("name", "")))
    results = [r for _, r in scored[:max_results]]

    return to_json({
        "source": "registry",
        "query": query,
        "type_filter": model_type,
        "results": results,
        "total_matches": len(scored),
        "showing": len(results),
    })


def _search_huggingface(query: str, model_type: str | None, max_results: int) -> str:
    """Search HuggingFace Hub API for models."""
    params = {
        "search": query,
        "sort": "downloads",
        "direction": "-1",
        "limit": max_results,
    }

    # Map model types to HuggingFace tags
    if model_type:
        type_tags = {
            "checkpoint": "diffusers",
            "lora": "lora",
            "vae": "vae",
            "controlnet": "controlnet",
            "embedding": "textual-inversion",
        }
        tag = type_tags.get(model_type.lower())
        if tag:
            params["filter"] = tag

    if not HUGGINGFACE_LIMITER().acquire(timeout=5.0):
        return to_json({"error": "Rate limited — too many HuggingFace requests. Try again shortly."})

    try:
        with httpx.Client() as client:
            resp = client.get(
                "https://huggingface.co/api/models",
                params=params,
                timeout=15.0,
            )
            resp.raise_for_status()
            data = resp.json()
    except httpx.ConnectError:
        return to_json({"error": "Could not reach HuggingFace API. Check your internet connection."})
    except httpx.HTTPStatusError as e:
        return to_json({"error": f"HuggingFace API returned {e.response.status_code}."})
    except Exception as e:
        return to_json({"error": f"HuggingFace search failed: {e}"})

    results = []
    for item in data:
        model_id = item.get("modelId", item.get("id", ""))
        results.append({
            "name": model_id,
            "author": model_id.split("/")[0] if "/" in model_id else "",
            "downloads": item.get("downloads", 0),
            "likes": item.get("likes", 0),
            "tags": item.get("tags", [])[:5],
            "url": f"https://huggingface.co/{model_id}",
            "last_modified": item.get("lastModified", ""),
        })

    return to_json({
        "source": "huggingface",
        "query": query,
        "type_filter": model_type,
        "results": results,
        "showing": len(results),
    })


def _handle_find_missing_nodes(tool_input: dict) -> str:
    path_str = tool_input.get("path")

    # Get workflow
    if path_str:
        path = Path(path_str)
        if not path.exists():
            return to_json({"error": f"File not found: {path_str}"})
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as e:
            return to_json({"error": f"Invalid JSON: {e}"})

        # Extract API-format nodes
        if "nodes" in data and isinstance(data["nodes"], list):
            prompt_data = data.get("extra", {}).get("prompt")
            if prompt_data and isinstance(prompt_data, dict):
                workflow = {
                    k: v for k, v in prompt_data.items()
                    if isinstance(v, dict) and "class_type" in v
                }
            else:
                # UI-only: extract class_types from nodes array
                workflow = {}
                for node in data["nodes"]:
                    nid = str(node.get("id", ""))
                    ntype = node.get("type", "")
                    if ntype:
                        workflow[nid] = {"class_type": ntype, "inputs": {}}
        else:
            workflow = {
                k: v for k, v in data.items()
                if isinstance(v, dict) and "class_type" in v
            }
    else:
        from .workflow_patch import get_current_workflow
        workflow = get_current_workflow()
        if workflow is None:
            return to_json({
                "error": (
                    "No workflow loaded. Either provide a 'path' or load one "
                    "with apply_workflow_patch first."
                ),
            })

    # Collect unique class_types
    class_types = set()
    for node in workflow.values():
        ct = node.get("class_type")
        if ct:
            class_types.add(ct)

    if not class_types:
        return to_json({"error": "No nodes found in workflow."})

    # Check which are available in live ComfyUI
    available = set()
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}/object_info", timeout=15.0)
            resp.raise_for_status()
            object_info = resp.json()
            available = set(object_info.keys())
    except httpx.ConnectError:
        return to_json({
            "error": "ComfyUI not reachable. Start ComfyUI to check node availability.",
        })
    except Exception as e:
        return to_json({"error": f"Could not fetch node info: {e}"})

    # Classify
    installed = sorted(class_types & available)
    missing = sorted(class_types - available)

    # Look up missing nodes in extension-node-map
    index = _build_node_to_pack()
    missing_report = []
    packs_needed = {}  # url -> {title, nodes}

    for node_type in missing:
        pack_info = index.get(node_type)
        if pack_info:
            url = pack_info["url"]
            if url not in packs_needed:
                packs_needed[url] = {
                    "title": pack_info["title"],
                    "url": url,
                    "installed": _is_pack_installed(url),
                    "missing_nodes": [],
                }
            packs_needed[url]["missing_nodes"].append(node_type)

            missing_report.append({
                "node_type": node_type,
                "pack_title": pack_info["title"],
                "pack_url": url,
                "pack_installed": _is_pack_installed(url),
            })
        else:
            missing_report.append({
                "node_type": node_type,
                "pack_title": None,
                "pack_url": None,
                "message": "Not found in ComfyUI Manager registry.",
            })

    # Summary
    if not missing:
        return to_json({
            "status": "all_installed",
            "total_node_types": len(class_types),
            "message": "All node types in this workflow are available.",
        })

    return to_json({
        "status": "missing_nodes",
        "total_node_types": len(class_types),
        "installed_count": len(installed),
        "missing_count": len(missing),
        "missing_nodes": missing_report,
        "packs_to_install": list(packs_needed.values()),
        "install_hint": (
            "Install missing packs via ComfyUI Manager or git clone into "
            f"{CUSTOM_NODES_DIR}"
        ),
    })


def _clear_cache():
    """Clear all in-memory caches, forcing reload from disk on next access."""
    _cache["custom_nodes"] = None
    _cache["extension_map"] = None
    _cache["node_to_pack"] = None
    _cache["model_list"] = None
    _freshness["custom_nodes_loaded_at"] = None
    _freshness["extension_map_loaded_at"] = None
    _freshness["model_list_loaded_at"] = None


def _file_age_info(path: Path) -> dict:
    """Get age info for a file. Returns dict with exists, modified_at, age_s, age_human."""
    if not path.exists():
        return {"exists": False, "path": str(path)}

    mtime = path.stat().st_mtime
    age_s = time.time() - mtime
    age_days = age_s / 86400

    if age_days < 1:
        age_human = f"{age_s / 3600:.1f} hours"
    else:
        age_human = f"{age_days:.1f} days"

    if age_s > _WARN_THRESHOLD:
        status = "very_stale"
    elif age_s > _STALE_THRESHOLD:
        status = "stale"
    else:
        status = "fresh"

    return {
        "exists": True,
        "path": str(path),
        "age_seconds": round(age_s),
        "age_human": age_human,
        "status": status,
    }


def _model_dir_stats() -> dict:
    """Count model files by type in the models directory."""
    if not MODELS_DIR.exists():
        return {"exists": False, "path": str(MODELS_DIR)}

    types = {}
    for subdir in sorted(MODELS_DIR.iterdir()):
        if subdir.is_dir():
            count = sum(1 for f in subdir.iterdir() if f.is_file() and f.suffix in (
                ".safetensors", ".ckpt", ".pt", ".pth", ".bin",
            ))
            if count > 0:
                types[subdir.name] = count

    return {
        "exists": True,
        "path": str(MODELS_DIR),
        "types": types,
        "total_files": sum(types.values()),
    }


def _handle_check_freshness(tool_input: dict) -> str:
    """Check freshness of registry data and model files."""
    if tool_input.get("refresh"):
        _clear_cache()

    # Check registry files
    registry_files = {
        "custom_node_list": _MANAGER_DIR / "custom-node-list.json",
        "extension_node_map": _MANAGER_DIR / "extension-node-map.json",
        "model_list": _MANAGER_DIR / "model-list.json",
    }

    registries = {}
    any_stale = False
    any_missing = False
    for key, path in sorted(registry_files.items()):
        info = _file_age_info(path)
        registries[key] = info
        if not info.get("exists"):
            any_missing = True
        elif info.get("status") in ("stale", "very_stale"):
            any_stale = True

    # Cache status
    cache_status = {
        "custom_nodes_cached": _cache["custom_nodes"] is not None,
        "extension_map_cached": _cache["extension_map"] is not None,
        "node_to_pack_cached": _cache["node_to_pack"] is not None,
        "model_list_cached": _cache["model_list"] is not None,
    }

    # Model directory stats
    models = _model_dir_stats()

    # Build recommendations
    recommendations = []
    if any_missing:
        recommendations.append(
            "Install ComfyUI Manager to get registry data: "
            "https://github.com/ltdrdata/ComfyUI-Manager"
        )
    if any_stale:
        recommendations.append(
            "Registry files are stale. Open ComfyUI Manager in the browser "
            "and click 'Update ComfyUI Manager' to refresh."
        )
    if tool_input.get("refresh"):
        recommendations.append("In-memory cache cleared. Next search will reload from disk.")

    return to_json({
        "registries": registries,
        "cache": cache_status,
        "models": models,
        "manager_installed": _MANAGER_DIR.exists(),
        "recommendations": recommendations,
        "refreshed": bool(tool_input.get("refresh")),
    })


