# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_save_session(tool_input: dict) -> str:
    name = tool_input["name"]

    # Capture current workflow state from workflow_patch
    from .workflow_patch import _state as wf_state
    workflow_state = copy.deepcopy(wf_state) if wf_state.get("current_workflow") else None

    # Preserve existing notes from prior add_note calls
    existing = load_session(name)
    notes = existing.get("notes", []) if "error" not in existing else None

    result = save_session(name, workflow_state=workflow_state, notes=notes)
    return to_json(result)


def _handle_load_session(tool_input: dict) -> str:
    name = tool_input["name"]
    session = load_session(name)

    if "error" in session:
        return to_json(session)

    # Restore workflow state if present
    wf = restore_workflow_state(session)
    restored_workflow = False

    if wf and wf.get("base_workflow") and wf.get("current_workflow"):
        from .workflow_patch import _state as wf_state
        wf_state["loaded_path"] = wf.get("loaded_path")
        wf_state["base_workflow"] = copy.deepcopy(wf["base_workflow"])
        wf_state["current_workflow"] = copy.deepcopy(wf["current_workflow"])
        wf_state["format"] = wf.get("format")
        wf_state["history"] = []  # Fresh undo history on restore
        restored_workflow = True

    notes = session.get("notes", [])

    return to_json({
        "loaded": name,
        "saved_at": session.get("saved_at", ""),
        "workflow_restored": restored_workflow,
        "workflow_path": wf.get("loaded_path") if wf else None,
        "notes": notes,
        "notes_count": len(notes),
    })


def _handle_list_sessions(tool_input: dict) -> str:
    result = list_sessions()
    return to_json(result)


def _handle_add_note(tool_input: dict) -> str:
    session_name = tool_input["session_name"]
    note = tool_input["note"]
    result = add_note(session_name, note)
    return to_json(result)


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a session tool call."""
    try:
        if name == "save_session":
            return _handle_save_session(tool_input)
        elif name == "load_session":
            return _handle_load_session(tool_input)
        elif name == "list_sessions":
            return _handle_list_sessions(tool_input)
        elif name == "add_note":
            return _handle_add_note(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except Exception as e:
        return to_json({"error": str(e)})

"""Tool registry for the ComfyUI SUPER DUPER Agent.

Each tool module exports:
  TOOLS: list[dict]    -- Anthropic tool schemas
  handle(name, input)  -- Execute a tool call, return result string

Intelligence layers (41 tools) + Brain layer (20 tools) = 61 tools total.
Brain tools are lazily imported to avoid circular dependencies
(brain modules import _util from this package).
"""

import logging

from . import comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat

log = logging.getLogger(__name__)

_MODULES = (comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat)

# Intelligence layer tool schemas
_LAYER_TOOLS: list[dict] = []
for _mod in _MODULES:
    _LAYER_TOOLS.extend(_mod.TOOLS)

# Map tool name -> handler module (intelligence layers)
_HANDLERS = {}
for _mod in _MODULES:
    for _tool in _mod.TOOLS:
        _HANDLERS[_tool["name"]] = _mod

# Brain tools are loaded lazily to break the circular import
_brain_loaded = False
_BRAIN_TOOL_NAMES: set[str] = set()


def _ensure_brain():
    """Lazily load brain layer tools."""
    global _brain_loaded, _BRAIN_TOOL_NAMES
    if _brain_loaded:
        return
    from ..brain import ALL_BRAIN_TOOLS
    _BRAIN_TOOL_NAMES.update(t["name"] for t in ALL_BRAIN_TOOLS)
    _brain_loaded = True


def _get_all_tools() -> list[dict]:
    """Get all tool schemas (intelligence + brain layers)."""
    _ensure_brain()
    from ..brain import ALL_BRAIN_TOOLS
    return _LAYER_TOOLS + list(ALL_BRAIN_TOOLS)


# Public API — ALL_TOOLS is a property-like accessor
class _ToolList(list):
    """Lazy tool list that includes brain tools on first access."""
    _initialized = False

    def _init_once(self):
        if not self._initialized:
            self._initialized = True
            self.extend(_LAYER_TOOLS)
            try:
                from ..brain import ALL_BRAIN_TOOLS
                self.extend(ALL_BRAIN_TOOLS)
            except ImportError:
                log.warning("Brain layer not available")

    def __iter__(self):
        self._init_once()
        return super().__iter__()

    def __len__(self):
        self._init_once()
        return super().__len__()

    def __getitem__(self, idx):
        self._init_once()
        return super().__getitem__(idx)


ALL_TOOLS = _ToolList()


def handle(name: str, tool_input: dict) -> str:
    """Dispatch a tool call to the right handler."""
    # Check brain tools (lazy loaded)
    _ensure_brain()
    if name in _BRAIN_TOOL_NAMES:
        from ..brain import handle as handle_brain
        return handle_brain(name, tool_input)

    # Intelligence layer tools
    mod = _HANDLERS.get(name)
    if mod is None:
        log.warning("Unknown tool called: %s", name)
        return f"Unknown tool: {name}"
    try:
        return mod.handle(name, tool_input)
    except Exception as e:
        log.error("Unhandled error in tool %s", name, exc_info=True)
        from ._util import to_json
        return to_json({"error": f"Internal error in {name}: {type(e).__name__}: {e}"})

