import httpx

from ..config import COMFYUI_HOST, COMFYUI_PORT, COMFYUI_URL
from ._util import to_json

log = logging.getLogger(__name__)

try:
    import websockets
    import websockets.sync.client
    _HAS_WS = True
except ImportError:
    _HAS_WS = False

